from money import cents

def total(lines, tax_rate):
    rate=Decimal(tax_rate)
    amount=Decimal('0.00')
    for price,quantity in lines:
        price=Decimal(price)
        if price < 0 or type(quantity) is not int or quantity < 0:
            raise ValueError('invalid line')
