from targets import dependencies

def order(targets):
    remaining={name:set(dependencies(targets,name)) for name in targets}
    if any(dep not in targets for deps in remaining.values() for dep in deps):
        raise ValueError('missing target')
    result=[]
    while remaining:
        ready=sorted(name for name,deps in remaining.items() if not deps)
        if not ready:
            raise ValueError('dependency cycle')
        name=ready[0]
        result.append(name)
        del remaining[name]
        for deps in remaining.values():
            deps.discard(name)
    return result

