class Cache:
    def __init__(self,clock):
        self.clock=clock
        self.entries={}
    def put(self,key,value,ttl):
        if ttl < 0:
            raise ValueError('negative TTL')
        self.entries[key]=Entry(value,self.clock()+ttl)
