from calendar_rules import is_open_day

def next_open(moment,holidays=()):
    day=moment.date()
    if is_open_day(day,holidays):
        if moment.time()<time(9):
            return datetime.combine(day,time(9))
        if moment.time()<time(17):
            return moment
