from graph import neighbors

def shortest(graph,start,goal):
    queue=[(0,start,[start])]
    seen=set()
    while queue:
        distance,node,path=heappop(queue)
        if node==goal: return (distance,path)
        if node in seen: continue
        seen.add(node)
        for target,cost in neighbors(graph,node):
            if target==goal: return (distance+cost,path+[target])
            heappush(queue,(distance+cost,target,path+[target]))
    return None

