from parser import parse

def compare(left,right):
    lmain,lpre=parse(left)
    rmain,rpre=parse(right)
    if lmain!=rmain:
        return (lmain>rmain)-(lmain<rmain)
    if lpre is None or rpre is None:
        return (lpre is None)-(rpre is None)
    for a,b in zip(lpre,rpre):
        if a==b: continue
        an,bn=a.isdigit(),b.isdigit()
        if an and bn:
            return (int(a)>int(b))-(int(a)<int(b))
        if an!=bn:
            return -1 if an else 1
        return (a>b)-(a<b)
    return (len(lpre)>len(rpre))-(len(lpre)<len(rpre))

def ordered(versions):
    return sorted(versions,key=cmp_to_key(compare))

