from encoding import byte_length

def chunks(text,max_bytes):
    if type(max_bytes) is not int or max_bytes<=0:
        raise ValueError('invalid byte limit')
    result=[]
    current=''
    size=0
    for character in text:
        width=byte_length(character)
        if width>max_bytes:
            raise ValueError('character does not fit')
        if size+width>max_bytes:
            result.append(current)
            current=''
            size=0
        current+=character
        size+=width
    if current:
        result.append(current)
    return result

